def numBusesToDestination(routes: list[list[int]], source: int, target: int) -> int:
    if source == target: return 0
    from collections import defaultdict, deque
    stop_to_buses = defaultdict(list)
    for bus_idx, route in enumerate(routes):
        for stop in route:
            stop_to_buses[stop].append(bus_idx)
    if source not in stop_to_buses or target not in stop_to_buses: return -1
    visited_buses = set()
    visited_stops = {source}
    q = deque([(source, 0)])
    while q:
        stop, buses_taken = q.popleft()
        if stop == target: return buses_taken
        for bus in stop_to_buses[stop]:
            if bus not in visited_buses:
                visited_buses.add(bus)
                for nxt_stop in routes[bus]:
                    if nxt_stop not in visited_stops:
                        visited_stops.add(nxt_stop)
                        q.append((nxt_stop, buses_taken + 1))
    return -1

